artifact.snippet:

// Quiz Answer Impact (how narrative choices affect axes)
export interface NarrativeAnswerImpact {
  axis_id: string;
  delta: number;                 // Change to apply (+/- value)
}

interface.signature:

import type { NarrativeAnswerImpact } from '$lib/ideology/types';

export interface NarrativeAnswerOption {
  text: string;
  impacts: NarrativeAnswerImpact[];
}

export interface NarrativeQuestion {
  id: number;
  story_text: string;
  optionA: NarrativeAnswerOption;
  optionB: NarrativeAnswerOption;
  tags: string[];
}


export interface NarrativeAnswerImpact {
  axis_id: string;
  delta: number;
}
